import type { AgentMarkState } from '@/lib/brand/agent-mark';

/**
 * The Nexstepper AI agent mark.
 *
 * Two opposing corner brackets closing in on one solid dot: the
 * brackets are the "precisely here" of an editorial annotation, the
 * dot is the point of view. Generated by the brand generator on
 * 2026-10-22; the source SVGs are in `public/brand/agent/`.
 *
 * ## Why it is inline SVG and not an <img>
 *
 * The mark has to ANIMATE. An `<img>` cannot change state, and a
 * sprite sheet or CSS mask would mean animating a background
 * position — which is not GPU-composited and looks cheap. Inline SVG
 * lets each part carry its own transform, and the motion layer in
 * `app/agent-mark.css` can drive them.
 *
 * ## Why the colour is `currentColor`
 *
 * The mark appears on white panels, on the dark app, and on the
 * indigo floating trigger button. Inheriting `currentColor` means
 * one asset works in all three without a second file. The dot is the
 * exception: it carries the agent's accent, and it changes colour by
 * state (indigo → amber → emerald → grey) because that colour IS
 * information.
 *
 * ## States
 *
 * `state` drives the whole motion language. See
 * `lib/brand/agent-mark.ts` for what each one means and what causes
 * it, and `app/dev/design-lab/agent-brand/` for the gallery.
 */

export type AgentMarkTone =
  /** Navy-on-light. The default. */
  | 'default'
  /** White strokes and a white dot — for a coloured (indigo) button. */
  | 'on-accent'
  /** Everything one colour — the single-colour stamp. */
  | 'monochrome';

export interface AgentMarkProps {
  /** Which moment of work the mark is showing. */
  state?: AgentMarkState;
  /** Rendered edge length in px. */
  size?: number | string;
  /** How the mark takes its colour from its surroundings. */
  tone?: AgentMarkTone;
  /**
   * Offset the mark's animation by this many ms. NEGATIVE values are
   * how the brand lab samples one cycle at several different moments
   * — six copies of the same mark, each a fraction of a cycle apart,
   * are a filmstrip of the motion in a still image.
   */
  delayMs?: number;
  /** Accessible name. Leave unset for a decorative mark beside a label. */
  label?: string;
  className?: string;
}

/** The two bracket strokes, from the generated artwork. */
const BRACKET_A = 'M 280 500 L 280 320 A 40 40 0 0 1 320 280 L 500 280';
const BRACKET_B = 'M 744 524 L 744 704 A 40 40 0 0 1 704 744 L 524 744';
/** The check that replaces the dot when an edit lands. */
const CHECK = 'M 486 512 L 505 531 L 540 490';

export function AgentMark({
  state = 'idle',
  size = 24,
  tone = 'default',
  delayMs = 0,
  label,
  className
}: AgentMarkProps) {
  const classes = ['agent-mark', className].filter(Boolean).join(' ');

  return (
    <svg
      viewBox="0 0 1024 1024"
      width={size}
      height={size}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={classes}
      data-state={state}
      data-tone={tone}
      style={{ '--agent-delay': `${delayMs}ms` } as React.CSSProperties}
      role={label ? 'img' : 'presentation'}
      aria-label={label}
      aria-hidden={label ? undefined : true}
    >
      {/* The two brackets. The wrapper carries the reading scan. */}
      <g data-part="scan">
        <g data-part="bracket-a">
          <path
            d={BRACKET_A}
            stroke="var(--agent-stroke)"
            strokeWidth="72"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </g>
        <g data-part="bracket-b">
          <path
            d={BRACKET_B}
            stroke="var(--agent-stroke)"
            strokeWidth="72"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </g>
      </g>

      {/* A soft halo behind the dot — the "alive" signal. */}
      <circle data-part="halo" cx="512" cy="512" r="54" />

      {/* The radar ring that pulses while an edit is in flight. */}
      <circle data-part="radar" cx="512" cy="512" r="54" />

      {/* The dot. Its colour is the agent's state colour. */}
      <g data-part="dot">
        <circle cx="512" cy="512" r="54" fill="var(--agent-dot)" />
      </g>

      {/* Drawn when an edit lands. */}
      <path data-part="check" d={CHECK} />
    </svg>
  );
}

export default AgentMark;
